{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        w = max(core[u], core[v], d)
        # canonicalize undirected endpoints (sort alphabetically)
        if u <= v:
            edges.append((u, v, w))
        else:
            edges.append((v, u, w))

    # Sort by weight, then by u, then by v (all stable)
    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find (Disjoint Set Union)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    needed = n - 1

    for u, v, w in edges:
        if len(mst_edges) == needed:
            break
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w

    if len(mst_edges) != needed:
        raise ValueError("Graph is disconnected; cannot compute MST")

    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
